// 1. Captura a resposta da API
const resposta = $input.first().json;

// VERIFICAÇÃO: Se não houver boletos ou a API retornar false
if (resposta.boletosEncontrado === false || !resposta.fatura || resposta.fatura.length === 0) {
  return {
    texto_final: "📄 *CONSULTA DE FATURAS*\n━━━━━━━━━━━━━━━━━━\n\nNenhuma fatura pendente foi encontrada no seu cadastro no momento. ✅\n\n━━━━━━━━━━━━━━━━━━\n_Deseja consultar outra coisa? Digite *0* para voltar ao menu._",
    faturas_mapeadas: [],
    nenhum_boleto: true // Flag extra caso queira usar num Switch depois
  };
}

const faturas = resposta.fatura;

// 2. Formata a lista e mapeia para o Redis
let listaFormatada = "📄 *FATURAS ENCONTRADAS*\n━━━━━━━━━━━━━━━━━━\n\n";
let faturasMapeadas = [];

faturas.forEach((item, index) => {
  const opcao = index + 1; 
  const dataFormatada = new Date(item.dt_fechamento).toLocaleDateString('pt-BR');
  const valorFormatado = item.vlr_bol.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

  // Limpa a linha digitável (sem espaços) com Regex
  const linhaLimpa = item.linha_dgt.replace(/\s+/g, '');

  listaFormatada += `${opcao}️⃣ *Boleto:* ${item.num_bol}\n`;
  listaFormatada += `📅 *Vencimento:* ${dataFormatada}\n`;
  listaFormatada += `💵 *Valor:* ${valorFormatado}\n`;

  // USANDO BLOCO DE CÓDIGO (```) PARA FACILITAR A CÓPIA NO WHATSAPP
  listaFormatada += `🔗 *Copia e Cola:*\n\`\`\`${linhaLimpa}\`\`\`\n\n`;

  // Guarda no mapeamento para o Redis ou próximo nó
  faturasMapeadas.push({
      indice: opcao,
      boleto_id: item.id_boleto, 
      numero_boleto: item.num_bol,
      linha: linhaLimpa
    });
});

listaFormatada += "━━━━━━━━━━━━━━━━━━\n";
listaFormatada += "👉 Digite o *número da opção* para baixar o PDF.";

return {
  texto_final: listaFormatada,
  faturas_mapeadas: faturasMapeadas,
  nenhum_boleto: false
};

