// 1. Captura a resposta da API (considerando que vem dentro de um array [0])
const resposta = $input.first().json;
const listaCcr = resposta.ccr || [];

if (listaCcr.length === 0) {
    return { texto_ccr: "⚠️ Nenhuma coleta foi localizada para o seu cadastro." };
}

// 2. Monta o cabeçalho
let mensagem = `📄 *CCRs LOCALIZADOS (${listaCcr.length})*\n`;
mensagem += "━━━━━━━━━━━━━━━━━━\n\n";

// 3. Percorre a lista e adiciona cada item
listaCcr.forEach((item, index) => {
    const data = new Date(item.dt_coleta).toLocaleDateString('pt-BR');
    const quantidade = item.quant_coleta > 0 ? `${item.quant_coleta} un/kg` : "Consulte no PDF";

    mensagem += `${index + 1}️⃣ *Coleta em ${data}*\n`;
    mensagem += `📦 *Qtd:* ${quantidade}\n`;
    mensagem += `🔗 *Link:* ${item.link}\n\n`;
});

mensagem += "━━━━━━━━━━━━━━━━━━\n";
mensagem += "_💡 Clique nos links acima para visualizar os documentos._";

return {
    texto_ccr: mensagem
};

