// 1. Captura a resposta da API
const resposta = $input.first().json;

// VERIFICAÇÃO: Se não houver contratos ou a API retornar contratoEncontrado como false
if (resposta.contratoEncontrado === false || !resposta.contratos || resposta.contratos.length === 0) {
  return {
    texto_final: "📜 *CONSULTA DE CONTRATOS*\n━━━━━━━━━━━━━━━━━━\n\nNão localizamos contratos ativos ou anteriores vinculados ao seu cadastro no momento. 📂\n\n━━━━━━━━━━━━━━━━━━\n_Digite *0* para voltar ao menu principal._",
    contratos_mapeados: [],
    sucesso_busca: false
  };
}

const contratos = resposta.contratos;

// 2. Formata a lista e mapeia para o Redis
let listaFormatada = "📜 *CONTRATOS LOCALIZADOS*\n━━━━━━━━━━━━━━━━━━\n\n";
let contratosMapeados = [];

contratos.forEach((item, index) => {
  const opcao = index + 1; // 1, 2, 3...

  // Formata a data de validade
  const dataValidade = new Date(item.dt_validade).toLocaleDateString('pt-BR');

  // Verifica se o contrato está vencido (comparando com a data de hoje)
  const hoje = new Date();
  const dataVenc = new Date(item.dt_validade);
  const status = dataVenc < hoje ? "🔴 *Expirado*" : "🟢 *Ativo*";

  listaFormatada += `${opcao}️⃣ *Contrato:* ${item.number}\n`;
  listaFormatada += `📅 *Validade:* ${dataValidade}\n`;
  listaFormatada += `📌 *Status:* ${status}\n\n`;

  // Guarda no mapeamento para identificação posterior
  contratosMapeados.push({
      indice: opcao,
      numero_contrato: item.number,
      validade: dataValidade
    });
});

listaFormatada += "━━━━━━━━━━━━━━━━━━\n";


return {
  texto_final: listaFormatada,
  contratos_mapeados: contratosMapeados,
  sucesso_busca: true
};

